from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework.permissions import IsAuthenticated
from rest_framework import status
from rest_framework_simplejwt.token_blacklist.models import OutstandingToken, BlacklistedToken

class RevokeTeamUserTokensView(APIView):
    permission_classes = [IsAuthenticated]

    def post(self, request, target_user_id):
        if not request.user.managed_team.filter(members__id=target_user_id).exists() and not request.user.is_staff:
            return Response({"detail": "Unauthorized to revoke sessions for target user"}, status=status.HTTP_403_FORBIDDEN)

        tokens = OutstandingToken.objects.filter(user_id=target_user_id)
        for token in tokens:
            BlacklistedToken.objects.get_or_create(token=token)
        return Response({"revoked_count": tokens.count(), "target_user_id": target_user_id})
